import clsx from "clsx";

type ButtonVariant = "primary" | "secondary" | "outline" | "ghost";

export function Button({
  children,
  className,
  variant = "primary",
  ...props
}: {
  children: React.ReactNode;
  className?: string;
  variant?: ButtonVariant;
} & React.ButtonHTMLAttributes<HTMLButtonElement>) {
  return (
    <button
      className={clsx(
        "inline-flex items-center justify-center rounded-full px-5 py-2.5 text-sm font-semibold transition-all",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-brand-primary",
        {
          primary: "bg-brand-primary text-white hover:bg-orange-500 shadow-card",
          secondary:
            "border border-neutral-300 bg-white text-neutral-900 hover:text-brand-primary hover:border-brand-primary",
          outline:
            "border border-neutral-300 bg-white text-neutral-900 hover:text-brand-primary hover:border-brand-primary",
          ghost: "text-neutral-700 hover:text-brand-primary",
        }[variant],
        className
      )}
      {...props}
    >
      {children}
    </button>
  );
}
